{{ config(materialized='table') }}

with
quarantined as (
    select
        entity_type,
        entity_external_id,
        classification_type_code,
        classification_value_code,
        effective_from,
        record_source,
        load_datetime,
        stage_recorded_at,
        violation_00,
        violation_01,
        violation_02
    from {{ ref("reference__deal_stage_history__checked") }}
),
violations as (
    select
        'entity_external_id_not_null' as rule_name,
        entity_type,
        entity_external_id,
        classification_type_code,
        classification_value_code,
        effective_from,
        record_source,
        load_datetime,
        stage_recorded_at
    from quarantined
    where violation_00

    union all

    select
        'classification_value_code_not_null' as rule_name,
        entity_type,
        entity_external_id,
        classification_type_code,
        classification_value_code,
        effective_from,
        record_source,
        load_datetime,
        stage_recorded_at
    from quarantined
    where violation_01

    union all

    select
        'effective_from_not_null' as rule_name,
        entity_type,
        entity_external_id,
        classification_type_code,
        classification_value_code,
        effective_from,
        record_source,
        load_datetime,
        stage_recorded_at
    from quarantined
    where violation_02
)

select
    rule_name,
    entity_type,
    entity_external_id,
    classification_type_code,
    classification_value_code,
    effective_from,
    record_source,
    load_datetime,
    stage_recorded_at
from violations
